export const sleep = \(ms\) => new Promise\(\(r\) => setTimeout\(r, ms\)\);

export class Page {
  constructor\(ws\) { this.ws = ws; this.id = 0; this.waiters = new Map\(\);
    ws.onmessage = \(e\) => { const m = JSON.parse\(e.data\);
      if \(m.id && this.waiters.has\(m.id\)\) { const { resolve, reject } = this.waiters.get\(m.id\); this.waiters.delete\(m.id\);
        m.error ? reject\(new Error\(JSON.stringify\(m.error\)\)\) : resolve\(m.result\); } };
  }
  static async attach\(port\) {
    const list = await \(await fetch\(`http://127.0.0.1:${port}/json/list`\)\).json\(\);
    const page = list.find\(\(t\) => t.type === "page"\);
    const ws = new WebSocket\(page.webSocketDebuggerUrl\);
    await new Promise\(\(r\) => \(ws.onopen = r\)\);
    const p = new Page\(ws\);
    await p.send\("Runtime.enable"\);
    return p;
  }
  send\(method, params = {}\) { const id = ++this.id;
    return new Promise\(\(resolve, reject\) => { this.waiters.set\(id, { resolve, reject }\);
      this.ws.send\(JSON.stringify\({ id, method, params }\)\); }\);
  }
  async js\(expression\) {
    const r = await this.send\("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true }\);
    if \(r.exceptionDetails\) throw new Error\(r.exceptionDetails.exception?.description ?? "js threw"\);
    return r.result.value;
  }
  async goto\(url\) { await this.send\("Page.navigate", { url }\); await sleep\(4000\); }
  async shot\(name\) {
    const r = await this.send\("Page.captureScreenshot", { format: "png" }\);
    const { writeFileSync } = await import\("node:fs"\);
    writeFileSync\(`/tmp/zyios/shots/${name}.png`, Buffer.from\(r.data, "base64"\)\);
  }
  async waitFor\(expression, ms = 20000, label = "condition"\) {
    const until = Date.now\(\) + ms;
    while \(Date.now\(\) < until\) {
      if \(await this.js\(`\(\(\) => { try { return Boolean\(${expression}\); } catch { return false; } }\)\(\)`\)\) return true;
      await sleep\(250\);
    }
    throw new Error\("timeout waiting for " + label\);
  }
  close\(\) { this.ws.close\(\); }
}
export function report\(label, ok, detail = ""\) {
  console.log\(`${ok ? "PASS" : "FAIL"}  ${label}${detail ? "  ::  " + detail : ""}`\);
}
EOF
